 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // Train and register the churn prediction model
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

 IDataView data = mlContext.Data.LoadFromTextFile<CustomerData>(
     dataPath, hasHeader: true, separatorChar: ',');

 var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

 // Map "Yes"/"No" string to boolean Label column
 var labelLookup = new[] {
     new LabelMapping { Churned = "Yes", Label = true },
     new LabelMapping { Churned = "No", Label = false }
 };
 var labelLookupData = mlContext.Data.LoadFromEnumerable(labelLookup);

 var pipeline = mlContext.Transforms.Conversion.MapValue(
         "Label", labelLookupData,
         labelLookupData.Schema["Churned"], labelLookupData.Schema["Label"],
         inputColumnName: nameof(CustomerData.Churned))
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerData.Age),
         nameof(CustomerData.Income),
         "RegionEncoded",
         nameof(CustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 var model = pipeline.Fit(split.TrainSet);

 // Evaluate
 var predictions = model.Transform(split.TestSet);
 var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
 Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");

 // Save model and register pooled prediction engine
 var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
 mlContext.Model.Save(model, split.TrainSet.Schema, modelPath);

 builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerRequest request) =>
 {
     var input = new CustomerData
     {
         Age = request.Age,
         Income = request.Income,
         Region = request.Region,
         PurchaseHistory = request.PurchaseHistory
     };
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel,
         Probability = prediction.Probability
     });
 });

 app.Run();

 // --- Data models ---

 public class CustomerData
 {
     [LoadColumn(0)]
     public float Age { get; set; }

     [LoadColumn(1)]
     public float Income { get; set; }

     [LoadColumn(2)]
     public string Region { get; set; } = string.Empty;

     [LoadColumn(3)]
     public float PurchaseHistory { get; set; }

     [LoadColumn(4)]
     public string Churned { get; set; } = string.Empty;
 }

 public class LabelMapping
 {
     public string Churned { get; set; } = string.Empty;
     public bool Label { get; set; }
 }

 public class ChurnPrediction
 {
     [ColumnName("PredictedLabel")]
     public bool PredictedLabel { get; set; }

     public float Probability { get; set; }
 }

 public record CustomerRequest(float Age, float Income, string Region, float PurchaseHistory);
